-- Authored class tags for rifts classes, one line each, from a reviewed
-- scripts/class-tags.mjs table. Derived tags (magic, psionics, mega-damage,
-- horror-factor) are computed from the class and never written.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~048-class-tags-rifts-1.sql
--
-- A TILDE SCRIPT ON PURPOSE: seven fix- scripts rewrite a class's whole
-- markdown, and any that sorted after this file would erase the tags on a
-- rebuild. Guarded on the class having no tags line, so a re-run is a no-op.
-- The tilde number is claimed at merge.

UPDATE imported_classes SET markdown = replace(markdown, char(10) || 'category: occ' || char(10), char(10) || 'category: occ' || char(10) || 'tags: [healer, divine]' || char(10)), updated_at = datetime('now') WHERE class_id = 'rifts-priest' AND instr(markdown, char(10) || 'tags:') = 0;
UPDATE imported_classes SET markdown = replace(markdown, char(10) || 'category: rcc' || char(10), char(10) || 'category: rcc' || char(10) || 'tags: [supernatural, aquatic]' || char(10)), updated_at = datetime('now') WHERE class_id = 'daitya' AND instr(markdown, char(10) || 'tags:') = 0;
